#define REBONDS_MAX 6
#define INDICE_REFRACTION 2.417
#define DISPERSION_CHROMATIQUE 0.085
#define NOMBRE_ECLATS 72

mat2 rotation2D(float angle) {
    float s = sin(angle), c = cos(angle);
    return mat2(c, -s, s, c);
}

mat3 matriceRotation(vec3 axe, float angle) {
    axe = normalize(axe);
    float s = sin(angle), c = cos(angle), oc = 1.0 - c;
    return mat3(
        oc * axe.x * axe.x + c,        oc * axe.x * axe.y - axe.z * s, oc * axe.z * axe.x + axe.y * s,
        oc * axe.x * axe.y + axe.z * s, oc * axe.y * axe.y + c,        oc * axe.y * axe.z - axe.x * s,
        oc * axe.z * axe.x - axe.y * s, oc * axe.y * axe.z + axe.x * s, oc * axe.z * axe.z + c
    );
}

struct Facette {
    vec3 normale;
    float distance;
};

Facette facettes[57];

void initialiserGeometrieDiamant() {
    float pi = 3.14159265359;
    int index = 0;

    facettes[index++] = Facette(vec3(0.0, 1.0, 0.0), 0.35);

    for (int i = 0; i < 8; i++) {
        float a = float(i) * (2.0 * pi / 8.0);
        facettes[index++] = Facette(normalize(vec3(cos(a) * 0.58, 0.82, sin(a) * 0.58)), 0.56);
        facettes[index++] = Facette(normalize(vec3(cos(a) * 0.66, -0.75, sin(a) * 0.66)), 0.62);
    }

    for (int i = 0; i < 16; i++) {
        float a = (float(i) + 0.5) * (2.0 * pi / 16.0);
        facettes[index++] = Facette(normalize(vec3(cos(a) * 0.67, 0.74, sin(a) * 0.67)), 0.59);
        facettes[index++] = Facette(normalize(vec3(cos(a) * 0.74, -0.67, sin(a) * 0.74)), 0.64);
    }

    for (int i = 0; i < 8; i++) {
        float a = float(i) * (2.0 * pi / 8.0) + (2.0 * pi / 16.0);
        facettes[index++] = Facette(normalize(vec3(cos(a) * 0.45, 0.89, sin(a) * 0.45)), 0.53);
    }
}

bool intersectionDiamantPrincipal(vec3 origineRayon, vec3 directionRayon, out float tProche, out float tLoin, out vec3 normaleProche, out vec3 normaleLoin) {
    tProche = 0.0;
    tLoin = 1e5;
    normaleProche = vec3(0.0);
    normaleLoin = vec3(0.0);

    float tempsModulo = mod(iTime, 20.0);

    for (int i = 0; i < 57; i++) {
        vec3 n = facettes[i].normale;
        float d = facettes[i].distance;

        if (tempsModulo >= 5.0 && tempsModulo < 10.0) {
            d += sin(iTime * 85.0 + float(i) * 3.1) * 0.015;
        }

        float denominateur = dot(directionRayon, n);
        float numerateur = d - dot(origineRayon, n);

        if (abs(denominateur) < 1e-6) {
            if (numerateur < 0.0) return false;
        } else {
            float t = numerateur / denominateur;
            if (denominateur < 0.0) {
                if (t > tProche) { tProche = t; normaleProche = n; }
            } else {
                if (t < tLoin) { tLoin = t; normaleLoin = n; }
            }
        }
    }
    return tProche < tLoin && tLoin > 0.0;
}

void obtenirTransformationEclat(int identifiant, float tempsExplosion, out vec3 centre, out vec3 axeRotation, out float angleRotation, out float echelle) {
    float fi = float(identifiant);

    vec3 directionAleatoire = normalize(vec3(
        sin(fi * 12.9898 + 1.1) * 2.2 - 0.1,
        abs(cos(fi * 4.1415 + 2.3)) * 2.8 + 0.3,
        sin(fi * 78.233 + 3.7) * 2.2 + 0.1
    ));

    float vitesse = 2.5 + fract(sin(fi * 43.12) * 9876.54) * 4.5;
    echelle = 0.025 + fract(sin(fi * 91.71) * 1234.56) * 0.04;

    float gravite = 5.5, yInitial = -0.1, hauteurSol = -1.2 + echelle;
    vec3 position = vec3(0.0, yInitial, 0.0) + directionAleatoire * vitesse * tempsExplosion + vec3(0.0, -0.5 * gravite * tempsExplosion * tempsExplosion, 0.0);

    if (position.y < hauteurSol) {
        float A = 0.5 * gravite, B = -directionAleatoire.y * vitesse, C = hauteurSol - yInitial;
        float discriminant = max(0.0, B * B - 4.0 * A * C);
        float tempsImpact = clamp((-B + sqrt(discriminant)) / (2.0 * A), 0.0, tempsExplosion);

        float tempsGlissement = tempsExplosion - tempsImpact;
        vec3 positionImpact = vec3(0.0, yInitial, 0.0) + directionAleatoire * vitesse * tempsImpact + vec3(0.0, -0.5 * gravite * tempsImpact * tempsImpact, 0.0);
        vec3 vitesseGlissement = vec3(directionAleatoire.x, 0.0, directionAleatoire.z) * vitesse * 0.6;

        position = positionImpact + vitesseGlissement * ((1.0 - exp(-tempsGlissement * 2.0)) / 2.0);
        position.y = hauteurSol;
    }

    centre = position;
    axeRotation = normalize(vec3(sin(fi * 3.3), cos(fi * 1.7), sin(fi * 8.9)));
    angleRotation = tempsExplosion * (5.0 + fract(sin(fi * 15.3) * 432.1) * 10.0);
}

const vec3 normalesOctaedre[8] = vec3[8](
    vec3( 0.57735,  0.57735,  0.57735), vec3(-0.57735,  0.57735,  0.57735),
    vec3( 0.57735, -0.57735,  0.57735), vec3(-0.57735, -0.57735,  0.57735),
    vec3( 0.57735,  0.57735, -0.57735), vec3(-0.57735,  0.57735, -0.57735),
    vec3( 0.57735, -0.57735, -0.57735), vec3(-0.57735, -0.57735, -0.57735)
);

bool intersectionOctaedre(vec3 origineRayon, vec3 directionRayon, float echelle, out float tProche, out float tLoin, out vec3 normaleProche, out vec3 normaleLoin) {
    tProche = 0.0; tLoin = 1e5;
    normaleProche = vec3(0.0); normaleLoin = vec3(0.0);

    for (int i = 0; i < 8; i++) {
        vec3 n = normalesOctaedre[i];
        float denominateur = dot(directionRayon, n), numerateur = echelle - dot(origineRayon, n);
        if (abs(denominateur) < 1e-5) {
            if (numerateur < 0.0) return false;
        } else {
            float t = numerateur / denominateur;
            if (denominateur < 0.0) {
                if (t > tProche) { tProche = t; normaleProche = n; }
            } else {
                if (t < tLoin) { tLoin = t; normaleLoin = n; }
            }
        }
    }
    return tProche < tLoin && tLoin > 0.0;
}

bool intersectionEclats(vec3 origineRayon, vec3 directionRayon, float tempsExplosion, out float tProche, out float tLoin, out vec3 normaleProche, out vec3 normaleLoin) {
    tProche = 1e5; tLoin = -1e5;
    normaleProche = vec3(0.0); normaleLoin = vec3(0.0);
    bool touche = false;

    for (int i = 0; i < NOMBRE_ECLATS; i++) {
        vec3 centre, axeRotation;
        float angleRotation, echelle;
        obtenirTransformationEclat(i, tempsExplosion, centre, axeRotation, angleRotation, echelle);

        vec3 origineRelative = origineRayon - centre;
        float b = dot(origineRelative, directionRayon);
        float c = dot(origineRelative, origineRelative) - echelle * echelle * 3.0;
        if ((b > 0.0 && c > 0.0) || (b * b - c < 0.0)) continue;

        mat3 matriceRot = matriceRotation(axeRotation, angleRotation);
        vec3 origineLocale = origineRelative * matriceRot, directionLocale = directionRayon * matriceRot;

        float tEclatProche, tEclatLoin;
        vec3 normaleEclatProche, normaleEclatLoin;
        if (intersectionOctaedre(origineLocale, directionLocale, echelle, tEclatProche, tEclatLoin, normaleEclatProche, normaleEclatLoin)) {
            if (tEclatProche < tProche) { tProche = tEclatProche; normaleProche = matriceRot * normaleEclatProche; touche = true; }
            if (tEclatLoin > tLoin) { tLoin = tEclatLoin; normaleLoin = matriceRot * normaleEclatLoin; }
        }
    }
    return touche && tProche > 0.0;
}

bool intersectionObjetScene(vec3 origineRayon, vec3 directionRayon, out float tProche, out float tLoin, out vec3 normaleProche, out vec3 normaleLoin) {
    float tempsModulo = mod(iTime, 20.0);
    if (tempsModulo < 10.0) return intersectionDiamantPrincipal(origineRayon, directionRayon, tProche, tLoin, normaleProche, normaleLoin);
    float tempsExplosion = (tempsModulo < 15.0) ? (tempsModulo - 10.0) : (20.0 - tempsModulo);
    return intersectionEclats(origineRayon, directionRayon, tempsExplosion, tProche, tLoin, normaleProche, normaleLoin);
}

vec3 obtenirArrierePlan(vec3 directionRayon) {
    vec3 couleur = mix(vec3(0.01, 0.015, 0.03), vec3(0.08, 0.1, 0.18), smoothstep(-0.2, 0.5, directionRayon.y));
    couleur += vec3(1.0, 0.95, 0.9) * pow(max(dot(directionRayon, normalize(vec3(1.0, 2.5, 1.5))), 0.0), 128.0) * 8.0;
    couleur += vec3(0.6, 0.85, 1.0) * pow(max(dot(directionRayon, normalize(vec3(-2.5, 1.5, -1.0))), 0.0), 64.0) * 5.0;
    couleur += vec3(1.0, 0.5, 0.8) * pow(max(dot(directionRayon, normalize(vec3(0.0, -2.0, 2.0))), 0.0), 32.0) * 3.0;
    return couleur;
}

float tracerCanalUnique(vec3 origineRayon, vec3 directionRayon, float indiceRefractionCanal, int indexCanal) {
    float tProche, tLoin; vec3 normaleProche, normaleLoin;
    if (!intersectionObjetScene(origineRayon, directionRayon, tProche, tLoin, normaleProche, normaleLoin) || tProche < 0.0) return 0.0;

    vec3 pointImpact = origineRayon + directionRayon * tProche, normale = normaleProche;
    float epsilon = (mod(iTime, 20.0) < 10.0) ? 0.001 : 0.0002;

    vec3 directionInterne = refract(directionRayon, normale, 1.0 / indiceRefractionCanal);
    if (length(directionInterne) == 0.0) directionInterne = reflect(directionRayon, normale);
    vec3 origineInterne = pointImpact + directionInterne * epsilon;

    float valeur = 0.0, poids = 1.0;

    for (int rebond = 0; rebond < REBONDS_MAX; rebond++) {
        if (!intersectionObjetScene(origineInterne, directionInterne, tProche, tLoin, normaleProche, normaleLoin)) break;

        vec3 pointRebond = origineInterne + directionInterne * tLoin, normaleRebond = normaleLoin;
        vec3 directionSortie = refract(directionInterne, -normaleRebond, indiceRefractionCanal);

        if (length(directionSortie) > 0.0) {
            vec3 couleurEnv = obtenirArrierePlan(directionSortie);
            valeur += (indexCanal == 0 ? couleurEnv.r : (indexCanal == 1 ? couleurEnv.g : couleurEnv.b)) * poids;
            break;
        }

        directionInterne = reflect(directionInterne, -normaleRebond);
        origineInterne = pointRebond + directionInterne * epsilon;
        poids *= 0.85;
    }
    return valeur;
}

vec3 RenduDiamant(vec3 origineRayon, vec3 directionRayon) {
    float tProche, tLoin; vec3 normaleProche, normaleLoin;
    if (!intersectionObjetScene(origineRayon, directionRayon, tProche, tLoin, normaleProche, normaleLoin) || tProche < 0.0) return vec3(0.0);

    vec3 pointImpact = origineRayon + directionRayon * tProche, normale = normaleProche;
    float fresnel = 0.04 + 0.96 * pow(1.0 - max(dot(-directionRayon, normale), 0.0), 5.0);
    vec3 reflexionSpeculaire = fresnel * obtenirArrierePlan(reflect(directionRayon, normale));

    vec3 indicesRefraction = vec3(INDICE_REFRACTION - DISPERSION_CHROMATIQUE, INDICE_REFRACTION, INDICE_REFRACTION + DISPERSION_CHROMATIQUE);
    vec3 couleurDispersion;
    for (int i = 0; i < 3; i++) {
        couleurDispersion[i] = tracerCanalUnique(origineRayon, directionRayon, indicesRefraction[i], i);
    }
    return reflexionSpeculaire + (1.0 - fresnel) * couleurDispersion;
}

vec3 afficherScene(vec3 origineRayon, vec3 directionRayon) {
    float hauteurSol = -1.2;
    float tSol = (hauteurSol - origineRayon.y) / directionRayon.y;

    float tProche, tLoin; vec3 normaleProche, normaleLoin;
    bool toucheObjet = intersectionObjetScene(origineRayon, directionRayon, tProche, tLoin, normaleProche, normaleLoin) && tProche > 0.0;

    if (toucheObjet && (tSol < 0.0 || tProche < tSol)) return RenduDiamant(origineRayon, directionRayon);

    if (tSol > 0.0) {
        vec3 positionSol = origineRayon + directionRayon * tSol;
        vec2 bordDalle = smoothstep(0.45, 0.49, abs(fract(positionSol.xz * 2.5) - 0.5));
        vec3 couleurSolBase = mix(vec3(0.92, 0.93, 0.95), vec3(0.25, 0.26, 0.28), max(bordDalle.x, bordDalle.y));

        float ombre = 1.0;
        if (intersectionObjetScene(positionSol + vec3(0.0, 0.02, 0.0), normalize(vec3(1.0, 2.5, 1.5)), tProche, tLoin, normaleProche, normaleLoin) && tProche > 0.0) ombre = 0.35;

        vec3 directionReflexion = reflect(directionRayon, vec3(0.0, 1.0, 0.0));
        vec3 reflexionSol = (intersectionObjetScene(positionSol, directionReflexion, tProche, tLoin, normaleProche, normaleLoin) && tProche > 0.0) ? RenduDiamant(positionSol, directionReflexion) : obtenirArrierePlan(directionReflexion);

        float fresnelSol = 0.15 + 0.85 * pow(1.0 - max(dot(-directionRayon, vec3(0.0, 1.0, 0.0)), 0.0), 3.0);
        return mix(couleurSolBase * ombre, reflexionSol, fresnelSol * 0.85);
    }
    return obtenirArrierePlan(directionRayon);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    initialiserGeometrieDiamant();

    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    float temps = iTime * 0.25;
    float distanceCamera = 1.6 + sin(iTime * 0.4) * 0.4;
    vec3 origineRayon = vec3(sin(temps) * distanceCamera, 1.6 + sin(iTime * 0.3) * 0.2, -cos(temps) * distanceCamera);
    vec3 pointVise = vec3(0.0, -0.2, 0.0);

    if (iMouse.z > 0.0) {
        vec2 m = iMouse.xy / iResolution.xy - 0.5;
        origineRayon = vec3(0.0, 1.5, -1.8);
        origineRayon.yz *= rotation2D(m.y * 3.14);
        origineRayon.xz *= rotation2D(-m.x * 6.28);
    }

    vec3 axeAvant = normalize(pointVise - origineRayon);
    vec3 axeDroit = normalize(cross(vec3(0.0, 1.0, 0.0), axeAvant));
    vec3 directionRayon = normalize(axeAvant + uv.x * axeDroit + uv.y * cross(axeAvant, axeDroit));

    vec3 couleur = afficherScene(origineRayon, directionRayon) * 1.2;
    couleur = (couleur * (2.51 * couleur + 0.03)) / (couleur * (2.43 * couleur + 0.59) + 0.14);

    fragColor = vec4(pow(clamp(couleur, 0.0, 1.0), vec3(0.4545)), 1.0);
}
